BEGIN;
SET LOCAL search_path = public;

WITH review_input (
  professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
  attendance_required, grade_received, engagement_level, tags, created_at, import_key, course_ids
) AS (
  VALUES 
    (256::BIGINT, 'Arrogante, le encanta que la gente llegue a llorarle para subir su ego, intenta ser "disruptivo" haciendo que los estudiantes den las clases de todo un mes, increiblemente cerrado de mente y super rencoroso. Evaluaciones y materia super confusa, que solo él lo entiende. Todo, menos respetado.'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores']::TEXT[], '2026-03-31T00:00:00+00:00'::TIMESTAMPTZ, 'e4f9450a4894fec04ff44e24445306ff90ce1cc9f391f1112d8d271b4b4e0b78'::TEXT, ARRAY[996, 120]::BIGINT[]),
    (256::BIGINT, 'El proyecto fue enorme, así que mejor buscar un buen grupo de trabajo. También porque 2 exámenes los hizo grupales y estaban relacionados con el proyecto. Si es molesto que se ponga en tanta cosa y eso lo complica para el proyecto, pero es buen profesor. No busca joder al estudiante'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Respetado por los estudiantes', 'Deja trabajos largos']::TEXT[], '2024-06-04T00:00:00+00:00'::TIMESTAMPTZ, '3cc4266f4d05b0b48894d9ab5f1d532cd9b9f57446099ae1815e0b10582e09d2'::TEXT, ARRAY[996]::BIGINT[]),
    (256::BIGINT, '2 exámenes, el desarrollo de un prototipo con monitoreo en tiempo real y un trabajo de investigación que prácticamente fue un anteproyecto de TFG. Sinceramente el curso estuvo sumamente pesado, pero puedo decir que aprendí bastante. No le recomiendo ir mucho a consulta porque a todo le pone un pero'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Deja trabajos largos', 'Clases excelentes']::TEXT[], '2023-12-04T00:00:00+00:00'::TIMESTAMPTZ, '34b0825078402d843fd37faed13aad42dfb5d03c21a82e74b1d2b16cf27234c2'::TEXT, ARRAY[120]::BIGINT[]),
    (256::BIGINT, 'Se la pasa hablando de vehículos eléctricos en vez de dar materia y cuando da materia no enseña ejemplos de nada. No cometa el error de hacer su proyecto de graduación basado en este curso a menos de que esté dispuesto a perder su identidad como ingeniero electromecánico.'::TEXT, 10.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-08-21T00:00:00+00:00'::TIMESTAMPTZ, '6b05b64403198b99271ab1c1d4639c19371af2b1bd31929e941230646cd9219d'::TEXT, ARRAY[113]::BIGINT[]),
    (256::BIGINT, '3 exámenes y un proyecto de investigación. Los exámenes realmente no son fáciles, son mucho de análisis. De ver si verdaderamente está comprendiendo la materia. Tienen que ponerle en el proyecto ya que vale un 25% del curso'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-05-27T00:00:00+00:00'::TIMESTAMPTZ, '4405b5ab7c39d703e7fad5d8fba26f2501ab31d7d394e4149a96775c4ff38972'::TEXT, ARRAY[976]::BIGINT[]),
    (256::BIGINT, 'El curso es tan provechoso como uno quiera, el profe habla constantemente de manera muy general de tecnologías que realmente no entiende a profundidad y lo admite. Es fácil de pasar aunque los examenes pueden ser confusos.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'La participación importa', 'Deja trabajos largos']::TEXT[], '2022-06-02T00:00:00+00:00'::TIMESTAMPTZ, 'beb56284cda0378c7c941b42b6e8836c54273178678d32ddbce51067db421156'::TEXT, ARRAY[120]::BIGINT[]),
    (256::BIGINT, 'No espere aprender mucho con este profe, siempre se desvía de los temas para hablar de cómo se debe innovar en los proyectos de graduación, todo tuanis que hable de eso al final de la clase pero es casi de lo único que habla. El curso no le va a aportar nada, solo un repaso sumamente general.'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-10-18T00:00:00+00:00'::TIMESTAMPTZ, 'aa2812369d1592783c6335b6df318d2e57b98abdfbfb3f18f4e6f0f06d475a08'::TEXT, ARRAY[120]::BIGINT[]),
    (256::BIGINT, 'La clase del profe se basa del libro de texto asignado por lo que recomiendo leerlo para pasar bien los exámenes, fuera de eso explica lo que pone en las presentaciones y da ejemplos de la vida real. El proyecto es individual y es suerte ya que le puede tocar un temá fácil o difícil de investigar.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación']::TEXT[], '2021-07-20T00:00:00+00:00'::TIMESTAMPTZ, '3bf2d928c65d4b73b2fb84e5d72cb9612af152ba15b274466aad2efaa7f7d9fb'::TEXT, ARRAY[976]::BIGINT[]),
    (256::BIGINT, 'Los labs se hacen de tarea, solo hay que concetarse a clase para que de las indicaiones ya que no sigue las indicaciones del manual, hace el lab a su manera y se brinca algunas cosas, algo desordenado, debes poner atencion a sus indicaciones y no tendras ningun problema.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Brinda apoyo']::TEXT[], '2021-07-19T00:00:00+00:00'::TIMESTAMPTZ, '56156b95a53ede3153861e2a00a4ac366e646ceca91b7b0115c88585391e21d9'::TEXT, ARRAY[925]::BIGINT[]),
    (256::BIGINT, 'Para Mante I y Mante II el mae es pésimo, pero cuando lleve predictivo(en el 2019) con él fue un profe completamente distinto. Fue un buen profe, solo lo recomendaría para este curso.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-07-05T00:00:00+00:00'::TIMESTAMPTZ, '790160d67657d190bd37e7ba09bed0bcf1ce2b4bc1899fb02b0657ee1cec0c70'::TEXT, ARRAY[120]::BIGINT[]),
    (256::BIGINT, 'Mante lleva como 10 años tratando de cambiar el nombre de la carrera. Los profes, los estudiantes y los egresados están de acuerdo en hacer el cambio, entonces: ¿Por qué si todos quieren el cambio se ha tardado tanto en hacer la transición? Respuesta: Piedra es el encargado, así de mediocre es'::TEXT, 8.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos']::TEXT[], '2021-02-28T00:00:00+00:00'::TIMESTAMPTZ, '21a11af454199e83680bd709f25ebc923246b62b2c66776cc481c090a4e7076d'::TEXT, ARRAY[996]::BIGINT[]),
    (256::BIGINT, 'Vaya a consulta solo para decirle la idea del proyecto y no vuelva más, se lo recomiendo si no quiere que le estén cambiando el proyecto todas la veces que vaya.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Clases largas']::TEXT[], '2021-01-25T00:00:00+00:00'::TIMESTAMPTZ, 'c1f14422839b7a01b3e7e8fdc16058a460f8bd7138e952214e0de9be8ee1890b'::TEXT, ARRAY[996]::BIGINT[]),
    (256::BIGINT, 'El peor profe del area administrativa, es muy idealista, inventa historias a su conveniencia, las clases son aburridas, no usa ejemplos, y califica a como él quiere, no deja retroalimentacion y en algunos casos nisiquiera evalua la materia. Vaya a consulta solo lo necesario.'::TEXT, 8.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2021-01-19T00:00:00+00:00'::TIMESTAMPTZ, '4b49fd0b9590368c5849262bcffc081abb0c8b2aa3bb86694903aed4a1b154c5'::TEXT, ARRAY[976, 996, 120, 3655, 3660]::BIGINT[]),
    (256::BIGINT, 'El profe es muy inestable, entonces en un momento da una indicación y la siguiente semana dice lo opuesto. Vaya a consulta solo lo necesario porque si va mucho el mae lo confunde más y no aclara nada. Al final casi que regala los proyectos. De fijo pasa, pero puede ser frustrante.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'La participación importa']::TEXT[], '2021-01-10T00:00:00+00:00'::TIMESTAMPTZ, '1afe298cf6f32bd55e6e8b94b9a8d7c97aef784be673c25aff21b28ae90e8d05'::TEXT, ARRAY[996]::BIGINT[]),
    (256::BIGINT, 'Este profe no sabe dar clases. Se confunde, se enreda y se sale del tema. Se echa de ver su falta de dominio y saca conclusiones no acorde con la materia. Hay que ser autodidacta.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2020-08-26T00:00:00+00:00'::TIMESTAMPTZ, '3a29e279597886bd8dd0ec43e4e81e341de4850b4d29f1dbf5b1e41841b713d7'::TEXT, ARRAY[976, 996, 120, 3655, 3660]::BIGINT[]),
    (256::BIGINT, 'Redacción de exámenes confusa y ambigua. En ocasiones cuesta que sea claro con las instrucciones de tareas y del proyecto ni se diga. Mucha anécdota que a veces suma a la materia y a veces no.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-25T00:00:00+00:00'::TIMESTAMPTZ, '17116aed257913fe16dce68e82f64d97c764d4b7b83688128d270cff3041fa29'::TEXT, ARRAY[976]::BIGINT[]),
    (256::BIGINT, 'Deja mucho trabajo y la mitad de las clases habla sobre cosas que no son de importancia para el curso, pero fijo pasa'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-26T00:00:00+00:00'::TIMESTAMPTZ, '843c3c86f325bf3647b807401a5bd9400aa2e3ff9d51f5fc8700fd6d14e6d559'::TEXT, ARRAY[976, 996, 120, 3655, 3660]::BIGINT[]),
    (256::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2018-05-04T00:00:00+00:00'::TIMESTAMPTZ, 'a74da570e565e9cfd2cc7c7e19152bb5415fd9bff54860f09da84ef24ade16a3'::TEXT, ARRAY[976]::BIGINT[]),
    (256::BIGINT, 'Pesimo.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-01-12T00:00:00+00:00'::TIMESTAMPTZ, '3995d6338b52e8bb713e036fab82531a3a3ba77b48922b9736f88ce5fa02ef90'::TEXT, ARRAY[976, 996, 3655]::BIGINT[]),
    (256::BIGINT, 'Le encanta hablar mal de la carrera, es pedante, puede llegar a ser insolente, pero lo que más aburre es que los trabajos nunca te da con claridad que es lo que quiere entonces te obliga ir a consulta y aún así la calificación que te da es muy subjetiva. Mejor llevar el curso con otro profesor.'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-12-02T00:00:00+00:00'::TIMESTAMPTZ, '7fd9d21fb4d5db145087f17040b2c670da2edbfa7985424c38a7e92c127a9a1c'::TEXT, ARRAY[976, 3655]::BIGINT[]),
    (256::BIGINT, 'Puede que tenga buenas intenciones, pero pésimo profesor y califica todo de manera subjetiva, usando como criterio cuántas veces se asistió a consulta. En clases no se aprende mucho'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores']::TEXT[], '2017-11-30T00:00:00+00:00'::TIMESTAMPTZ, 'b313ffe71f4d6af1b6a45b9d6aebbabe3a34267b2cb7dccba0bb84e7098488ef'::TEXT, ARRAY[976, 3655]::BIGINT[]),
    (256::BIGINT, 'Esa Piedra mejor se la brinca, aprenderá mucho sobre la vida personal del profe y nada importante..... machista, prepotente,'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Exámenes retadores']::TEXT[], '2016-06-23T00:00:00+00:00'::TIMESTAMPTZ, 'ca960d7f3bbdd740876375ac274835bc1b161cc991aabf26d78222f59206e1e8'::TEXT, ARRAY[976]::BIGINT[]),
    (256::BIGINT, 'Es buen profe, un poco exigente pero al final valora el esfuerzo de aquellos que le ponen. Como persona es buena nota bastante tratable'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-07-04T00:00:00+00:00'::TIMESTAMPTZ, '23a8df2804181352eb8b8d8f088c2eb3a92d22cf97a090d05dc89f363f8d1684'::TEXT, ARRAY[925]::BIGINT[]),
    (256::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-01T00:00:00+00:00'::TIMESTAMPTZ, '6fa7e31f8fd601756ba7c29c1ddca476b2a5add684e8ddf639192d3f5304ee8e'::TEXT, ARRAY[996, 976]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
